# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def make(last, first):
    return Student("id", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        students = [make("Halloway", "Juno"), make("Dunmere", "Piet"), make("Zed", "Al")]
        self.assertEqual(
            seating_rows(students, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno", "Row 2: Zed, Al"]
        )

    def test_bad_seat_count(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([make("A", "B")], seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
